#include "engine/native_population_registry.hpp"
#include <iostream>
#include "domain/next_life.hpp"
#include "domain/hatchling_path.hpp"
#include <sstream>
using namespace stalthos;using namespace stalthos::fauna;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
std::string actorState(const ActorSnapshot&a){std::ostringstream s;s.precision(17);s<<a.id<<","<<int(a.species)<<","<<a.position.x<<","<<a.position.y<<","<<a.position.z<<","<<a.headingRadians<<","<<a.distanceTravelledMeters<<","<<a.site<<","<<a.target<<","<<a.calendarAge<<","<<int(a.stage)<<","<<a.hunger<<","<<a.thirst<<","<<a.fatigue<<","<<a.injury<<","<<a.isResting<<","<<int(a.activity);return s.str();}
std::string ledgerState(const ResourceLedgerDto&l){std::ostringstream s;s.precision(17);for(auto&r:l.resources)s<<r.id<<","<<int(r.kind)<<","<<r.initialQuantity<<","<<r.consumedQuantity<<";";for(auto&k:l.sessions)s<<k.sessionId<<","<<k.resourceId<<","<<k.amount<<";";return s.str();}
int main(){try{
std::vector<HabitatSite> sites{{{0,0,0},true,false,{1}},{{2,0,0},false,true,{0}}};Population p(42,1001,sites,8);
ResourceLedgerDto ledger{{{100,ResourceKind::Shrub,10,1},{200,ResourceKind::Creek,10,2}},{{7,100,1},{8,200,2}}};uint64_t next=100;
engine::NativePopulationRegistry h(p,ledger,{},{{0,100,sites[0].position},{1,200,sites[1].position}},next);
const auto emptyHeroSession=next++; (void)emptyHeroSession; auto before=h.snapshot();auto oldSessions=h.sessions();const auto oldLedger=ledgerState(h.ledger());auto oldNext=next;
auto admit=[&](Identity id,const std::vector<Vec3>&path,RegionalAdmissionOrigin origin=RegionalAdmissionOrigin::PhysicalArrival){return h.admitHatchling(id,path,0,next,{1,2},origin);};
check(admit(999,{{.5,0,0}},RegionalAdmissionOrigin::CameraPrewarm)==RegionalAdmission::CameraOnly,"camera birth accepted");check(next==oldNext&&h.actors().size()==8,"camera mutated owner");
check(admit(2,{{.5,0,0}})==RegionalAdmission::IdentityConflict,"excluded hero accepted");check(admit(before.actors[0].id,{{.5,0,0}})==RegionalAdmission::IdentityConflict,"existing identity accepted");check(admit(999,{})!=RegionalAdmission::Accepted,"empty path accepted");check(admit(999,{{5,0,0}})!=RegionalAdmission::Accepted,"unsupported long edge accepted");
next=7;check(admit(999,{{.5,0,0}})==RegionalAdmission::SessionConflict && next==7,"history session accepted or advanced");next=oldSessions.front().second;check(admit(999,{{.5,0,0}})==RegionalAdmission::SessionConflict,"empty-history NPC binding collision accepted");next=oldNext;check(admit(999,{{.5,0,0}})==RegionalAdmission::Accepted,"valid hatch denied");auto after=h.snapshot();check(after.actors.size()==9&&h.sessions().size()==9&&next==oldNext+1,"not one fresh child/session");for(size_t i=0;i<8;++i)check(actorState(before.actors[i])==actorState(after.actors[i]),"old actor mutated at birth");check(oldLedger==ledgerState(h.ledger()),"history changed at birth");const auto bindingsAfter=h.sessions();for(auto b:oldSessions)check(std::find(bindingsAfter.begin(),bindingsAfter.end(),b)!=bindingsAfter.end(),"binding lost");check(after.actors.back().stage==LifeStage::Hatchling&&after.actors.back().calendarAge==0,"not actual newborn");check(admit(999,{{.5,0,0}})==RegionalAdmission::IdentityConflict,"duplicate accepted");
const auto continuation=h.continuation();auto r=h.registry();check(r.restoreContinuation(continuation),"same admitted graph cannot restore continuation");
h.advance({1,2},true);auto moved=h.snapshot().actors.back();check(moved.calendarAge==2&&moved.distanceTravelledMeters>0&&moved.hunger>.12,"independent ordinary evolution missing");const auto position=moved.position;const auto priorLedger=ledgerState(h.ledger());h.advanceDormant({3,4});auto dormant=h.snapshot().actors.back();check(dormant.calendarAge==6&&dormant.position.x==position.x&&dormant.position.z==position.z,"dormancy moved or double aged");check(priorLedger==ledgerState(h.ledger()),"dormant resource contact");
uint64_t birthSession=1000;engine::NativePopulationRegistry h2(p,ledger,{},{{0,100,sites[0].position},{1,200,sites[1].position}},birthSession);check(h2.admitHatchling(2,{{.5,0,0}},0,birthSession,{1})==RegionalAdmission::Accepted,"child2 denied");StalthosState world(42);world.setHero(1,1);world.heroDied();std::vector<Identity> ids;for(const auto&a:h2.actors())ids.push_back(a.id);check(domain::beginNextLife(world,1,ids,birthSession).hero==3,"next life collided with child2");
h.advanceDormant({0,0});auto dormantCount=h.actors().size();auto dormantNext=next;check(admit(998,{{.5,0,0}})!=RegionalAdmission::Accepted && h.actors().size()==dormantCount && next==dormantNext,"inactive birth mutated owner");uint64_t fullSession=1000;engine::NativePopulationRegistry full(Population(42,1001,sites,16),ledger,{},{{0,100,sites[0].position},{1,200,sites[1].position}},fullSession);auto fullNext=fullSession;check(full.admitHatchling(998,{{.5,0,0}},0,fullSession,{1})==RegionalAdmission::IndividualLimit && fullSession==fullNext && full.actors().size()==16,"capacity denial mutated owner");auto route=domain::hatchlingPath({.5,0,0},sites,[](double,double)->std::optional<double>{return 0;});check(route && route->points.front().x==.5,"local supported route missing");check(!domain::hatchlingPath({.5,0,0},sites,[](double,double)->std::optional<double>{return std::nullopt;}),"wet/unresident route accepted");check(!domain::hatchlingPath({.5,0,0},sites,[](double x,double)->std::optional<double>{return x*2;}),"steep/height-mismatched route accepted");
std::cout<<"HATCH_REVIEW_OK atomic rejection old_actor_binding_history retained unique_session actual_lifecycle_needs_motion continuation dormant\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}



